// Extract crosslink data from WF-02's POST body
const body = $input.item.json.body || $input.item.json;

const entryId = body.entry_id;
const fileName = body.file_name;
const relatedIds = body.related_ids || [];
const relatedCount = body.related_count || relatedIds.length;
const tags = body.tags || [];
const entities = body.entities || [];
const summary = body.summary || '';

if (!entryId) {
  throw new Error('No entry_id in payload');
}

return {
  json: {
    entry_id: entryId,
    file_name: fileName,
    related_ids: relatedIds,
    related_count: relatedCount,
    tags: tags,
    entities: entities,
    summary: summary
  }
};

const prev = $('Parse Payload').item.json;
const fromHttp = $input.item.json;
const related = Array.isArray(fromHttp) ? fromHttp : (prev.related_entries || []);
if (!prev.related_ids || prev.related_ids.length === 0) {
  return { json: { ...prev, related_entries: [] } };
}
return { json: { ...prev, related_entries: related } };

// Build a Slack notification message
const data = $input.item.json;
const relatedEntries = data.related_entries || [];
const count = data.related_count;
const fileName = data.file_name || 'unknown';
const tags = data.tags || [];
const entities = data.entities || [];
const summary = data.summary || '';

// Build the matched entries list (top 10)
const entryLines = relatedEntries.slice(0, 10).map((e, i) => {
  const eTags = (e.tags || []).slice(0, 3).join(', ');
  const shortSummary = (e.summary || '').substring(0, 80);
  return `${i + 1}. *${e.file_name}* — _${shortSummary}${shortSummary.length >= 80 ? '...' : ''}_ [${eTags}]`;
}).join('\n');

const moreText = relatedEntries.length > 10 ? `\n_...y ${relatedEntries.length - 10} mas_` : '';

const message = `:link: *Crosslink Alert: ${count} conexiones encontradas*\n\n` +
  `*Entrada nueva:* \`${fileName}\`\n` +
  (summary ? `*Resumen:* ${summary}\n` : '') +
  `*Tags:* ${tags.join(', ')}\n` +
  `*Entidades:* ${entities.join(', ')}\n\n` +
  `*Entradas relacionadas:*\n${entryLines}${moreText}\n\n` +
  `_La espiral conecta ${count} nodos._`;

return {
  json: {
    slack_message: message,
    entry_id: data.entry_id,
    related_count: count
  }
};
